Rellenar sudoku# Enunciado# Realizar un subalgoritmo con todos los subalgoritmos necesarios para rellenar un sudoku casilla por casilla. El algoritmo mostrará en pantalla el sudoku parcialmente relleno, teniendo en cuenta que:
Aquellas casillas que estén rellenas mostrarán el número introducido. Las casillas vacías mostrarán los posibles valores que pueden introducirse. El algoritmo solicitará al usuario la casilla que desea rellenar (fila y columna) y el valor que desea introducir. El valor se guardará en la casilla si éste es un valor válido para la posición (véase las normas del sudoku) y se mostrará al usuario el estado actual del sudoku.
Soluciones# Diseño en Pseudocódigo# PROCEDIMIENTO Inicializa( VAR m ) ENTRADAS: (*Ninguna*) SALIDAS: m: ARRAY (0..8,0..8,0..9) DE ENTEROS (*Matriz con los valores a 0 y los posibles valores a 1*) VARIABLES: i,j,k: ENTEROS INICIO PARA i&lt;--0 HASTA 8 HACER PARA j&lt;--0 HASTA 8 HACER m(i,j,0) &lt;-- 0 PARA k&lt;--1 HASTA 9 HACER m(i,j,k) &lt;-- 1 FIN_PARA FIN_PARA FIN_PARA FIN_PARA //---------------------------------- PROCEDIMIENTO Pinta( m ) ENTRADAS: m: ARRAY (0..8,0..8,0..9) DE ENTEROS (*Matriz con los valores y los posibles valores*) SALIDAS: (*Muestra por pantalla la matriz del sudoku, mostrando los valores disponibles en aquellas casillas donde no se ha introducido aún ningún valor*) VARIABLES: p: ARRAY (0..36,0..36) DE CARACTERES i, j, k, x, y: ENTEROS INICIO (*Inicializar la matriz p que se mostrará en pantalla*) PARA i&lt;--0 HASTA 36 HACER PARA j&lt;--0 HASTA 36 HACER p(i,j) &lt;-- &#39; &#39; FIN_PARA FIN_PARA (*Colocar bordes*) PARA i&lt;--0 HASTA 36 HACER p(0,i) &lt;-- GRUESO p(36,i) &lt;-- GRUESO p(i,0) &lt;-- GRUESO p(i,36) &lt;-- GRUESO FIN_PARA PARA i&lt;--1 HASTA 35 HACER PARA j&lt;--4 HASTA 35 CON INCREMENTO 4 HACER p(j,i) &lt;-- FINO p(i,j) &lt;-- FINO FIN_PARA FIN_PARA PARA i&lt;--1 HASTA 35 HACER PARA j&lt;--12 HASTA 35 CON INCREMENTO 12 HACER p(j,i) &lt;-- GRUESO p(i,j) &lt;-- GRUESO FIN_PARA FIN_PARA (*Volcar matriz de enteros en matriz de caracteres*) PARA i&lt;--0 HASTA 8 HACER PARA j&lt;--0 HASTA 8 HACER SI m(i,j,0)&lt;&gt;0 ENTONCES x &lt;-- 2+(4*i) y &lt;-- 2+(4*j) p(x,y) &lt;-- CHR(ORD(&#39;0&#39;)+m(i,j,0)) SI_NO PARA k&lt;--1 HASTA 9 HACER x &lt;-- 1+(4*i)+((k-1) DIV 3) y &lt;-- 1+(4*j)+((k-1) MOD 3) SI m(i,j,k)&lt;&gt;0 ENTONCES p(x,y) &lt;-- CHR(ORD(&#39;0&#39;)+k) FIN_SI FIN_PARA FIN_SI FIN_PARA FIN_PARA (*Pintar pantalla*) PARA i&lt;--0 HASTA 36 HACER PARA j&lt;--0 HASTA 36 HACER ESCRIBIR p(i,j) FIN_PARA ESCRIBIR SaltoDeLinea FIN_PARA ESCRIBIR SaltoDeLinea FIN //---------------------------------- FUNCION LeerEntero(min, max): ENTERO ENTRADAS: min: ENTERO (*Valor mínimo que se puede leer*) max: ENTERO (*Valor máximo que se puede leer*) SALIDAS: (*Un valor entero comprendido entre min y max*) VARIABLES: valor: ENTERO INICIO REPETIR LEER valor SI valor&lt;min O valor&gt;max ENTONCES ESCRIBIR &#34;El valor debe estar entre&#34;, min, &#34; y &#34;, max, &#34;. Vuelva a Introducirlo.&#34; FIN_SI HASTA valor&gt;=min Y valor&lt;=max DEVOLVER valor FIN //---------------------------------- PROCEDIMIENTO QuitarOpcion( VAR m, x, y, v ) ENTRADAS: m: ARRAY (0..8,0..8,0..9) DE ENTEROS (*Matriz con valores y posibles valores*) x,y: ENTEROS (*Coordenadas donde se ha introducido el valor*) v: ENTERO (*Valor introducido*) SALIDAS: m: ARRAY (0..8,0..8,0..9) DE ENTEROS (*Matriz donde se han eliminado v como posible valor en las celdas correspondientes*) VARIABLES: i,j,f,c: ENTEROS PARA i&lt;--0 HASTA 8 HACER m(x,i,v) &lt;-- 0 (*Quitar opción en fila*) m(i,y,v) &lt;-- 0 (*Quitar opición en columna*) FIN_PARA (*Quitar opición en submatriz*) f &lt;-- (x DIV 3)*3 c &lt;-- (y DIV 3)*3 PARA i&lt;--f HASTA f+2 HACER PARA j&lt;--c HASTA c+2 HACER m(i,j,v) &lt;-- 0 FIN_PARA FIN_PARA FIN //---------------------------------- ALGORITMO CreaSudoku ENTRADAS: x, y: ENTEROS (*Coordenadas de una casilla del sudoku*) valor: ENTERO (*Valor a Introducir en la casilla x,y*) SALIDAS: (*Valores fijos y posibles de cada casilla del sudoku*) sudoku: ARRAY (0..8,0..8,0..9) DE ENTEROS VARIABLES: (*No son necesarias*) CONSTANTES: GRUESO=&#39;*&#39; FINO=&#39; &#39; INICIO Inicializa( sudoku ) Pinta( sudoku ) ESCRIBIR &#34;Introduzca el valor de la casilla (0 para salir): &#34; valor &lt;-- LeerEntero(0,9) MIENTRAS valor &lt;&gt; 0 HACER ESCRIBIR &#34;Introduzca la fila (0-8): &#34; x &lt;-- LeerEntero(0,8) ESCRIBIR &#34;Introduzca la columna (0-8): &#34; y &lt;-- LeerEntero(0,8) SI sudoku(x,y,valor) = 0 ENTONCES ESCRIBIR &#34;Ese valor no se puede poner en la casilla. Elija uno nuevo.&#34; SI_NO SI sudoku(x,y,0) &lt;&gt; 0 ENTONCES ESCRIBIR &#34;La casilla ya tiene un valor. Elija otra casilla.&#34; SI_NO sudoku(x,y,0) &lt;-- valor QuitarOpcion( sudoku, x, y, valor ) FIN_SI FIN_SI Pinta( sudoku ) ESCRIBIR &#34;Introduzca el valor de la casilla (0 para salir): &#34; valor &lt;-- LeerEntero(0,9) FIN_MIENTRAS FINPrograma en C# #include &lt;stdio.h&gt; #include &lt;stdlib.h&gt; #define GRUESO &#39;*&#39; //#define GRUESO 219 #define FINO &#39; &#39; //---------------------------------- void Inicializa( int m[9][9][10] ){ int i,j,k; for(i=0; i&lt;=8; i++){ for(j=0; j&lt;=8; j++){ m[i][j][0]=0; for(k=1; k&lt;=9; k++){ m[i][j][k]=1; } } } } //---------------------------------- void Pinta( int m[9][9][10] ){ char p[37][37]; int i, j, k, x, y; //Inicializar for(i=0; i&lt;=36; i++){ for(j=0; j&lt;=36; j++){ p[i][j]=&#39; &#39;; } } //Colocar bordes for(i=0;i&lt;=36;i++){ p[0][i]=GRUESO; p[36][i]=GRUESO; p[i][0]=GRUESO; p[i][36]=GRUESO; } for(i=1; i&lt;=35; i++){ for(j=4; j&lt;=35; j+=4){ p[j][i]=FINO; p[i][j]=FINO; } } for(i=1; i&lt;=35; i++){ for(j=12; j&lt;=35; j+=12){ p[j][i]=GRUESO; p[i][j]=GRUESO; } } //Volcar matriz de enteros en matriz de caracteres for(i=0; i&lt;=8; i++){ for(j=0; j&lt;=8; j++){ if(m[i][j][0]!=0){ x=2+(4*i); y=2+(4*j); p[x][y]=&#39;0&#39;+m[i][j][0]; }else{ for(k=1; k&lt;=9; k++){ x=1+(4*i)+((k-1)/3); y=1+(4*j)+((k-1)%3); if(m[i][j][k]!=0){ p[x][y]=&#39;0&#39;+k; } } } } } //Pintar pantalla for(i=0; i&lt;=36; i++){ for(j=0; j&lt;=36; j++){ printf(&#34;%c&#34;, p[i][j]); } printf(&#34;
