&#34;, min, max); } }while(entero&lt;min || entero&gt;max); return( entero ); } //---------------------------------- void QuitarOpcion( int m[9][9][10], int x, int y, int v ){ int i,j,f,c; for (i=0; i&lt;=8; i++){ m[x][i][v]=0; //Quitar en fila m[i][y][v]=0; //Quitar en columna } //Quitar en submatriz f=(x/3)*3; c=(y/3)*3; for(i=f; i&lt;=f+2; i++){ for(j=c; j&lt;=c+2; j++){ m[i][j][v]=0; } } } //---------------------------------- int main( void ){ int sudoku[9][9][10]; int x, y, valor; Inicializa( sudoku ); Pinta( sudoku ); printf(&#34;Introduzca el valor de la casilla (0 para salir): &#34;); valor=LeerEntero(0,9); while(valor!=0){ printf(&#34;Introduzca la fila (0-8): &#34;); x=LeerEntero(0,8); printf(&#34;Introduzca la columna (0-8): &#34;); y=LeerEntero(0,8); if(sudoku[x][y][valor]==0){ printf(&#34;Ese valor no se puede poner en la casilla. Elija uno nuevo.
&#34;); }else{ if(sudoku[x][y][0]!=0){ printf(&#34;La casilla ya tiene un valor. Elija otra casilla.
&#34;); }else{ sudoku[x][y][0]=valor; QuitarOpcion( sudoku, x, y, valor ); } } Pinta( sudoku ); printf(&#34;Introduzca el valor de la casilla (0 para salir): &#34;); valor=LeerEntero(0,9); } system(&#34;PAUSE&#34;); }

Transformar un texto# Enunciado# El siguiente programa lee un texto cualquiera y lo escribe al revés transformando las mayúsculas en minúsculas y viceversa. Para esto último basta tener en cuenta que la diferencia entre el código ASCII de una letra mayúscula y el de la misma letra en minúscula es la misma para todas las letras del abecedario. Hay que tener cuidado para no modificar los caracteres de estilo tales como espacio en blanco (&rsquo; &lsquo;), tabulador (&rsquo;\t&rsquo;), coma (,), &hellip;
Soluciones# Programa en C por Angel# Solución comentada del Ejercicio:
/* fichero inverso.c */ /* Este programa convierte las mayusculas en minusculas y viceversa */ /* y escribe el texto cambiado al reves */ #include &lt;stdio.h&gt; void main(void) { int ch; char texto[101]; /* limite de caracteres del texto */ int i, n, dif; dif=&#39;a&#39;-&#39;A&#39;; printf(&#34;Introduce un texto de no mas de 100 caracteres.\n&#34;); printf(&#34;Pulsa ^Z para finalizar:\n&#34;); i=0; while ((ch=getchar())!=EOF) { if ((ch&gt;=&#39;a&#39;)&amp;&amp;(ch&lt;=&#39;z&#39;)) /* es minúscula */ ch-=dif; else if ((ch&gt;=&#39;A&#39;)&amp;&amp;(ch&lt;=&#39;Z&#39;)) /* es mayúscula */ ch+=dif; texto[i++]=ch; } texto[i]=&#39;\0&#39;; for (n=i; n&gt;=0; n--) printf(&#34;%c&#34;, texto[n]); printf(&#34;\n&#34;); }Comentario# Como ya se ha visto, en C se utiliza la constante simbólica EOF para indicar el final de un fichero (esta constante está definida en el fichero stdio.h). Su valor numérico es (−1) y equivale también a z (^z) cuando se introduce el texto desde teclado.
En este programa se utiliza la forma de introducir la cadena como ya se hizo en el programa frase.c. Para cambiar las mayúsculas a minúsculas y viceversa hay que chequear el carácter y ver si es alfabético o no. Una vez que se sabe que es un carácter alfabético, hay que tener en cuenta que el código ASCII correspondiente a la &ldquo;A&rdquo; es el 65 y el correpondiente a la &ldquo;a&rdquo; es el 97, es decir, la diferencia entre ambos es 32. La misma diferencia se mantiene para otras letras entre la minúscula y la mayúscula. En lugar de teclear el texto cada vez, puedes crear un fichero de texto llamado texto1.txt y redireccionar la entrada del programa con el operador (&lt;) si ejecutas el programa desde la línea de comandos, en la forma: &gt; inverso &lt; texto1.txt.
